def fewestArcs(n, arcs):
    m = 2 * n
    ends = [0] * (m + 1)
    starts = set()
    for s, length in arcs:
        starts.add(s)
        if s + length > ends[s]:
            ends[s] = s + length
        if s + n + length > ends[s + n]:
            ends[s + n] = s + n + length
    g = [0] * (m + 1)
    run = 0
    for x in range(m + 1):
        if ends[x] > run:
            run = ends[x]
        g[x] = min(m, max(x, run))
    LOG = max(1, n.bit_length() + 1)
    up = [g]
    for _ in range(1, LOG):
        prev = up[-1]
        up.append([prev[prev[x]] for x in range(m + 1)])
    INF = 10 ** 9
    best = INF
    for s in starts:
        target = s + n
        x = s
        cnt = 0
        for j in range(LOG - 1, -1, -1):
            y = up[j][x]
            if y < target:
                x = y
                cnt += 1 << j
        if g[x] >= target:
            best = min(best, cnt + 1)
    return -1 if best == INF else best
